INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `BroadcastTextID0`, `lang0`, `Probability0`, `em0_0`, `em0_1`, `em0_2`, `em0_3`, `em0_4`, `em0_5`)
VALUES
(87571, 'Hail.$B$BI am Galak Twoclubs.$B$BI''m only wielding one club you say? Hah, I keep the other one hidden for special occasions.$B$BFeel the wind at your back friend, and keep your weapons close. You never know when you might need to use them.$B$BSpeaking of which, I can teach you how.', 'Hail.$B$BI am Galak Twoclubs.$B$BI''m only wielding one club you say? Hah, I keep the other one hidden for special occasions.$B$BFeel the wind at your back friend, and keep your weapons close. You never know when you might need to use them.$B$BSpeaking of which, I can teach you how.', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(30501, 'Some think that Tauren are not worthy to be Starcallers. They don''t understand that Taurens worship the same being Night Elves call Elune under a different name, Mu''sha, the Eye of the Earthmother.', 'Some think that Tauren are not worthy to be Starcallers. They don''t understand that Taurens worship the same being Night Elves call Elune under a different name, Mu''sha, the Eye of the Earthmother.', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(130501, 'Mu''sha''s light shines only on Starcallers, $C. The stars have not chosen you for this path.', 'Mu''sha''s light shines only on Starcallers, $C. The stars have not chosen you for this path.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(32037, 'The earthmother guides me, I am not simply bound by the elements themselves. Free yourself, let the earthmother bring you wisdom.$B$BBecome one with the earth, $C. Let me teach you what I mean..', 'The earthmother guides me, I am not simply bound by the elements themselves. Free yourself, let the earthmother bring you wisdom.$B$BBecome one with the earth, $C. Let me teach you what I mean..', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(132037, 'The life-giving spirits speak only to Primalists, $C. Nature has not chosen you as its champion.', 'The life-giving spirits speak only to Primalists, $C. Nature has not chosen you as its champion.', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(40042, 'An''she''s light guides us all. When darkness falls, it is by her power that we will create a new dawn.', 'An''she''s light guides us all. When darkness falls, it is by her power that we will create a new dawn.', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(240042, 'Solar magic serves only the pure of purpose, $C. Your motivations are unclear.', 'Solar magic serves only the pure of purpose, $C. Your motivations are unclear.', 0, 0, 1, 0, 0, 0, 0, 0, 0);
