INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`)
VALUES
(10300, 'Keeper of the inner flame,$B$BThe fire that stirs in your spirit must be tended, or it will consume you. I will teach you to feed it and to bind it.$B$BFind me beside the kiln of Camp Narache.$B$BApprentice Yahk Loregrain$BPyromancer Trainer', 0),
(10301, 'Listener,$B$BThe whispers beyond the veil have spoken your name. Few of our people dare to answer them. You will.$B$BFind me in the shadow of the huts on the west side of Camp Narache.$B$BUltha Dreamharrow$BCultist Trainer', 0),
(10302, 'Child of the Earthmother,$B$BMu''sha watches you from the night sky. The stars on this chart have waited for you to read them.$B$BFind me beneath the great totem at the heart of Camp Narache.$B$BOko''une, Chosen of Lo''sho$BStarcaller Trainer', 0),
(10303, 'Bearer of the dawn,$B$BAn''she''s light burns brighter when you are near. Carry this prayer, and learn to wield her radiance as weapon and shield.$B$BFind me by the brazier at the east tepee of Camp Narache.$B$BSunwalker Thunderhorn$BSun Cleric Trainer', 0),
(10304, 'Keeper-to-be,$B$BThe marks on this stone are older than the first shaman''s song. Learn to read them, and you will learn to write upon the world itself.$B$BFind me among the totems at the east edge of Camp Narache.$B$BGo''hro$BRunemaster Trainer', 0),
(10305, 'Wild one,$B$BThe earth shifted under your hooves and the fire leaned toward you. The elements know you; now they must learn to obey you.$B$BFind me in the chieftain''s lodge of Camp Narache.$B$BAmuwate Eagledream$BPrimalist Trainer', 0),
(10306, 'Protector of the tribes,$B$BThe guardian stands between danger and those who cannot protect themselves. Like the great mesas, you will become immovable.$B$BFind me near the warrior''s circle of Camp Narache.$B$BMotah Stonebreaker$BGuardian Trainer', 0),
(10307, 'Storm-touched,$B$BThe sky gathered above you and held back its rain. That fury sleeps in you still. I will teach you to wake it.$B$BFind me by the great drum of Camp Narache.$B$BTooantuh Cloudtail$BStormbringer Trainer', 0),
(10308, 'Warrior,$B$BThe rage of the ancestors runs in your blood. Rage without aim is wasted. I will teach you to aim it.$B$BFind me at the hide rack on the east side of Camp Narache.$B$BGalak Twoclubs$BBarbarian Trainer', 0),
(10309, 'Champion of justice,$B$BYou took only what the hunt required and harmed none without need. Such restraint is where the Templar''s path begins.$B$BFind me beneath the lamps by the south-east totem of Camp Narache.$B$BJax Dawnsoar$BTemplar Trainer', 0),
(10310, 'Tracker,$B$BYou read the trail where others saw only grass. The wilds have marked you; now learn to guard them.$B$BFind me at the archery range on the west side of Camp Narache.$B$BNawat Windhorn$BRanger Trainer', 0);
